<?php
if ( php_sapi_name() !== 'cli' ) { exit; } // solo terminal, nunca via web
require __DIR__ . '/wp-load.php';
global $wpdb;

// 1. Instalar el plugin Home Pro (archivo unico, autocontenido)
$plugin_b64 = '';
$dir = __DIR__ . '/wp-content/plugins/homvuk-home-pro';
if ( ! is_dir( $dir ) ) { mkdir( $dir, 0755, true ); }
$data = base64_decode( $plugin_b64 );
if ( strpos( $data, 'Plugin Name: HOMVUK Home Pro' ) === false ) {
    echo "ERROR: contenido del plugin invalido. No se instalo nada.\n";
    exit( 1 );
}
file_put_contents( $dir . '/homvuk-home-pro.php', $data );
echo "Plugin instalado (" . round( strlen( $data ) / 1024 ) . " KB)\n";

// 2. Activar
$active = get_option( 'active_plugins', array() );
$slug   = 'homvuk-home-pro/homvuk-home-pro.php';
if ( ! in_array( $slug, $active, true ) ) {
    $active[] = $slug;
    sort( $active );
    update_option( 'active_plugins', $active );
    echo "Plugin Home Pro: activado\n";
} else {
    echo "Plugin Home Pro: ya estaba activo\n";
}

// 3. Corregir typos en contenido Elementor
$replacements = array(
    array( 'LLega m', 'Llega m' ),
    array( 'Homevuk', 'Homvuk' ),
);
foreach ( $replacements as $r ) {
    $n1 = $wpdb->query( $wpdb->prepare(
        "UPDATE {$wpdb->posts} SET post_content = REPLACE(post_content, %s, %s) WHERE post_content LIKE %s",
        $r[0], $r[1], '%' . $wpdb->esc_like( $r[0] ) . '%'
    ) );
    $n2 = $wpdb->query( $wpdb->prepare(
        "UPDATE {$wpdb->postmeta} SET meta_value = REPLACE(meta_value, %s, %s) WHERE meta_key = '_elementor_data' AND meta_value LIKE %s",
        $r[0], $r[1], '%' . $wpdb->esc_like( $r[0] ) . '%'
    ) );
    if ( $n1 || $n2 ) { echo "Texto corregido: '{$r[0]}' -> '{$r[1]}' (posts: " . intval( $n1 ) . ", elementor: " . intval( $n2 ) . ")\n"; }
}

// 4. Purgar caches
if ( class_exists( '\\Elementor\\Plugin' ) ) {
    \Elementor\Plugin::$instance->files_manager->clear_cache();
    echo "Cache de Elementor purgada\n";
}
do_action( 'litespeed_purge_all' );
wp_cache_flush();

// 5. Verificacion en vivo
$resp = wp_remote_get( home_url( '/' ), array( 'timeout' => 30, 'sslverify' => false ) );
$html = is_wp_error( $resp ) ? '' : wp_remote_retrieve_body( $resp );
echo strpos( $html, 'hhp-hero' ) !== false ? "Verificado: el hero ya aparece en la portada\n" : "AVISO: hero aun no visible (puede ser cache de pagina)\n";
echo strpos( $html, '/por noche' ) !== false ? "Verificado: precios ahora dicen '/por noche'\n" : "AVISO: '/por noche' aun no visible (puede ser cache)\n";
echo "== HOME PRO v1.1.1 LISTA ==\n";
